"use strict";
import { createColumnHelper } from "@tanstack/react-table";
import { Table } from "components/Table";
import { Cell } from "components/Table/Cell";
import { ClickableHeaderRow, HeaderArrow, HeaderCell, HeaderSortText, TableText } from "components/Table/styled";
import { MAX_WIDTH_MEDIA_BREAKPOINT } from "components/Tokens/constants";
import { OrderDirection } from "graphql/data/util";
import { useUserVaultTransactions } from "hooks/morpho";
import { useMemo, useState } from "react";
import { ExternalLink } from "react-feather";
import { Flex, Text, styled, useMedia, useSporeColors } from "ui/src";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { useAccount } from "wagmi";
const TableWrapper = styled(Flex, {
  m: "0 auto",
  maxWidth: MAX_WIDTH_MEDIA_BREAKPOINT,
  width: "100%"
});
function SortableHeader({
  label,
  isSorted,
  direction,
  onSort
}) {
  return <ClickableHeaderRow justifyContent="flex-start" onPress={onSort} group>
      <HeaderSortText active={isSorted} variant="body3">
        {label}
      </HeaderSortText>
      {isSorted && <HeaderArrow orderDirection={direction} size={14} />}
      {!isSorted && <Flex width={14} />}
    </ClickableHeaderRow>;
}
function YourTransactionTableComponent({
  transactions,
  loading
}) {
  const media = useMedia();
  const colors = useSporeColors();
  const neutral2Color = colors?.neutral2?.val ?? "#9CA3AF";
  const [sortState, setSortState] = useState({ id: "date", desc: true });
  const columns = useMemo(() => {
    const columnHelper = createColumnHelper();
    return [
      columnHelper.accessor("date", {
        id: "date",
        header: () => <HeaderCell justifyContent="flex-start">
            <ClickableHeaderRow
          justifyContent="flex-start"
          onPress={() => setSortState((prev) => ({ id: "date", desc: !prev.desc }))}
          group
        >
              <HeaderSortText active={sortState.id === "date"} variant="body3">
                Date
              </HeaderSortText>
              <HeaderArrow
          orderDirection={sortState.desc ? OrderDirection.Desc : OrderDirection.Asc}
          size={14}
          opacity={sortState.id === "date" ? 1 : 0}
        />
            </ClickableHeaderRow>
          </HeaderCell>,
        cell: (info) => <Cell height="100%" justifyContent="flex-start" loading={loading}>
            <TableText>{info.getValue?.() ?? ""}</TableText>
          </Cell>,
        size: 200
      }),
      columnHelper.accessor("type", {
        id: "type",
        header: () => <HeaderCell justifyContent="flex-start">
            <Text variant="body3" color="$neutral2" fontWeight="500">
              Type
            </Text>
          </HeaderCell>,
        cell: (info) => <Cell height="100%" justifyContent="flex-start" loading={loading}>
            <TableText>{info.getValue?.() ?? ""}</TableText>
          </Cell>,
        size: 150
      }),
      columnHelper.accessor("amount", {
        id: "amount",
        header: () => <HeaderCell justifyContent="flex-start">
            <Text variant="body3" color="$neutral2" fontWeight="500">
              Amount
            </Text>
          </HeaderCell>,
        cell: (info) => {
          const row = info.row?.original;
          if (!row) {
            return <Cell height="100%" justifyContent="flex-start" loading={loading} />;
          }
          return <Cell height="100%" justifyContent="flex-start" loading={loading}>
              <Flex row alignItems="center" gap="$gap8">
                <div
            style={{
              width: 24,
              height: 24,
              backgroundColor: "#2775CA",
              borderRadius: "50%",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              color: "white",
              fontSize: 10,
              fontWeight: "bold"
            }}
          >
                  $
                </div>
                <TableText>{row.amount}</TableText>
                <Flex
            backgroundColor="$surface3"
            paddingHorizontal="$spacing8"
            paddingVertical="$spacing2"
            borderRadius="$roundedFull"
          >
                  <Text variant="body4" color="$neutral2">
                    {row.amountUsd}
                  </Text>
                </Flex>
              </Flex>
            </Cell>;
        },
        size: 250
      }),
      columnHelper.accessor("txHash", {
        id: "txHash",
        header: () => <HeaderCell justifyContent="flex-start">
            <Text variant="body3" color="$neutral2" fontWeight="500">
              Transaction
            </Text>
          </HeaderCell>,
        cell: (info) => <Cell height="100%" justifyContent="flex-start" loading={loading}>
            <Flex row alignItems="center" gap="$gap8" style={{ cursor: "pointer" }}>
              <TableText>{info.getValue?.() ?? ""}</TableText>
              <Text
          transition="all 0.2s ease"
          color={colors.neutral2.val}
          hoverStyle={{ color: colors.neutral3.val }}
          cursor="pointer"
        >
                <ExternalLink size={14} />
              </Text>
            </Flex>
          </Cell>,
        size: 150
      })
    ];
  }, [loading, sortState, neutral2Color]);
  return <Table
    columns={columns}
    data={transactions}
    loading={loading}
    maxWidth={1200}
    tableType="vaultx"
    tableHeight={64}
  />;
}
export default function YourTransactionTable({ vaultAddress }) {
  const { address: userAddress } = useAccount();
  const chainId = UniverseChainId.Mainnet;
  const { data: userTransactions, isLoading: isLoadingUserTx } = useUserVaultTransactions(userAddress, chainId, 50);
  const filteredTransactions = useMemo(() => {
    if (!userTransactions) return [];
    if (!vaultAddress) return userTransactions;
    return userTransactions.filter((tx) => tx.vaultId.toLowerCase() === vaultAddress.toLowerCase());
  }, [userTransactions, vaultAddress]);
  const formattedTransactions = useMemo(() => {
    return filteredTransactions.map((tx) => ({
      id: tx.id,
      date: tx.date,
      type: tx.type,
      amount: tx.amount,
      amountUsd: tx.amountUsd,
      tokenSymbol: tx.tokenSymbol,
      txHash: tx.txHash
    }));
  }, [filteredTransactions]);
  return <TableWrapper>
      <YourTransactionTableComponent transactions={formattedTransactions} loading={isLoadingUserTx} />
    </TableWrapper>;
}
