"use strict";
import { Flex } from "ui/src";
import ApyChart from "./ApyChart";
import OverviewTable from "./OverviewTable";
import SharePriceChart from "./SharePriceChart";
import TotalDepositChart from "./TotalDepositChart";
export default function OverviewTab({ vault }) {
  return <Flex flexDirection="column" gap="$spacing24">
      {
    /* Share Price Chart */
  }
      <SharePriceChart sharePrice={vault.sharePrice} assetSymbol={vault.token.symbol} vaultAddress={vault.address} />
      {
    /* Total Deposits Chart */
  }
      <TotalDepositChart
    totalDepositsUsd={vault.depositsUsd}
    assetSymbol={vault.token.symbol}
    hasUsdPricing={(vault.tokenPriceUsd ?? 0) > 0}
    vaultAddress={vault.address}
  />
      {
    /* APY Chart */
  }
      <ApyChart apy={vault.apy} feePercent={vault.feePercent} vaultAddress={vault.address} />
      {
    /* Overview Table */
  }
      <OverviewTable />
    </Flex>;
}
