"use strict";
import SegmentControl from "components/SegmentControl";
import { Flex, Text } from "ui/src";
import { NumberType, useFormatter } from "utils/formatNumbers";
import { ChartContainer, HeaderRow, ValueText } from "../ChartProperties";
export default function TotalDepositChart({
  totalDepositsUsd,
  assetSymbol,
  hasUsdPricing
}) {
  const { formatFiatPrice } = useFormatter();
  return <ChartContainer>
      <HeaderRow>
        <Text variant="body3" color="$neutral2">
          Total Deposits (USD)
        </Text>
        <Flex flexDirection="row" gap="$gap8">
          <SegmentControl options={[assetSymbol]} />
        </Flex>
      </HeaderRow>
      <ValueText>
        {hasUsdPricing ? formatFiatPrice({ price: totalDepositsUsd, type: NumberType.FiatTokenStats }) : "--"}
      </ValueText>
      <Flex height={60} justifyContent="center" alignItems="center">
        <Text variant="body3" color="$neutral3">
          Current value
        </Text>
      </Flex>
    </ChartContainer>;
}
